const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
class DatabaseMigrator {
  constructor(migrationsDir = './migrations/') {
    this.migrationsDir = path.resolve(migrationsDir);
  }

  // Read all SQL files from the migrations directory
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);
      // Filter for .sql files and sort them to ensure correct order
      return files
        .filter(file => path.extname(file).toLowerCase() === '.sql')
        .sort()  // Alphabetical sort (assumes files are named like 001_..., 002_...)
        .map(file => path.join(this.migrationsDir, file));
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`Migrations directory not found: ${this.migrationsDir}`);
      } else {
        console.error('Error reading migration directory:', err.message);
      }
      return [];
    }
  }

  // Apply migrations
  run() {
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log('Applying migrations...');
    migrationFiles.forEach(filePath => {
      console.log(`Applying migration: ${path.basename(filePath)}`);
      // In a real scenario, you'd execute the SQL file here
    });
    console.log('Migration process complete.');
  }
}

// Execute migration
if (require.main === module) {
  const migrator = new DatabaseMigrator();
  migrator.run();
}

module.exports = DatabaseMigrator;

