// Read all .sql files from the migrations directory, sorted by filename
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);
    return files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort()
      .map(file => path.join(MIGRATIONS_DIR, file));
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Error: Migrations directory not found:', MIGRATIONS_DIR);
    } else {
      console.error('Error reading migration directory:', err.message);
    }
    return [];
  }
}

// Main execution
function run() {
  console.log('Scanning migrations directory:', MIGRATIONS_DIR);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found. Exiting.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s). Applying:`);
  migrationFiles.forEach(file => {
    console.log(`→ ${path.basename(file)}`);
  });
}

