        .sort();

      // Log each migration file that would be applied
      console.log('Applying migrations:');
      sqlFiles.forEach(file => {
        console.log(`- ${file}`);
      });
    });
  } catch (error) {
    console.error('Error running migrations:', error);
    process.exit(1);
  }
}

// Execute the migration process
